void saveRepair(){if(repairRun.empty())return;repairRun["updated"]=timestamp();atomicWrite(store->root/"config/repairs"/(str(repairRun,"id")+".json"),repairRun.dump(2));}
void finishRepair(const std::string& state,const std::string& message){repairActive=false;if(!repairRun.empty()){repairRun["state"]=state;repairRun["message"]=message.substr(0,1000);saveRepair();}status=wide(message);}
